package org.example.strategy_pattern.delivery.impl;import org.example.strategy_pattern.delivery.Order;import org.example.strategy_pattern.delivery.ShippingStrategy;public class StandardShippingStrategy implements ShippingStrategy {    @Override    public int calculateFee(Order order) {        int baseFee = 30;        if (order.getWeightInGram() > 1000) {            baseFee += 5;        }        return baseFee;    }}